  c.strokeStyle='#8b9fa6';c.lineWidth=9;c.beginPath();c.moveTo(px(160),py(origin+1500));c.lineTo(px(160),py(origin+TAXI_LAYOUT.rearZ));c.lineTo(px(0),py(origin+TAXI_LAYOUT.rearZ));c.lineTo(px(0),py(origin+TAXI_LAYOUT.startZ));c.stroke();
