document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));$('openHangar').onclick=()=>showTab('hangar');$('backToPlan').onclick=()=>showTab('career');$('previewOrbit').onclick=()=>previewAngle=(previewAngle+1)%4;
document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{job=b.dataset.job;updatePlan();});for(const id of ['airport','destination','weather','difficulty'])$(id).onchange=()=>{updatePlan();if(id==='weather'){const p=readMenuWorld();world.build(p);setLighting(p);}if(id==='airport'&&!active){const p=readMenuWorld();world.build(p);}};
for(const [id,key] of [['soundEnabled','sound'],['ringsEnabled','rings'],['quality','quality']])$(id).onchange=()=>{profile.settings[key]=id==='quality'?$(id).value:$(id).checked;persist();configureQuality();};
$('unlock').onclick=()=>{try{purchase(profile,selected);persist();renderProfile();updatePlan();toast(PLANES[selected].name+' dołącza do Waszej floty!');}catch(error){toast(error.message);}};
$('start').onclick=()=>begin();$('freeFlight').onclick=()=>begin('free');$('resumeFlight').onclick=async()=>{try{sound.unlock();await enterFlight(Flight.restore(profile.current));say('Lot przywrócony. Sprawdź przyrządy i kontynuuj.');}catch(error){profile.current=null;persist();renderProfile();toast('Nie udało się przywrócić tego lotu. Postępy kariery zostały zachowane.');}};
for(const [id,name] of [['service','service'],['engine','engine'],['radio','tower'],['gear','gear'],['flaps','flaps'],['repair','repair'],['divert','divert'],['runway','runway']])$(id).onclick=()=>{action(name);if(id==='divert')$('failurePanel').classList.add('hidden');};
$('groundAssist').onclick=()=>action('assist');
$('camera').onclick=()=>{if(active&&!paused)setCockpit(!cockpit);};$('orbit').onclick=()=>{if(active&&!paused){$('cameraPanel').classList.toggle('hidden');$('failurePanel').classList.add('hidden');$('navPanel').classList.add('hidden');}};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(!active||paused)return;if(b.dataset.view==='cockpit')setCockpit(true);else{setCockpit(false);angle=Number(b.dataset.view);}$('cameraPanel').classList.add('hidden');});$('map').onclick=()=>{$('navPanel').classList.toggle('hidden');$('failurePanel').classList.add('hidden');updateHud();};$('failure').onclick=()=>{$('failurePanel').classList.toggle('hidden');$('navPanel').classList.add('hidden');};document.querySelectorAll('[data-failure]').forEach(b=>b.onclick=()=>{action('failure',b.dataset.failure);$('failurePanel').classList.add('hidden');});
$('pause').onclick=pause;$('resume').onclick=()=>{if(active?.finished&&active.plan.mode==='free')return enterFlight(new Flight(active.plan));paused=false;$('modal').classList.add('hidden');sound.unlock();};$('returnMenu').onclick=returnMenu;$('tips').onclick=()=>{const open=$('missionPanel').classList.toggle('expanded');$('tips').setAttribute('aria-expanded',String(open));};
$('exportSave').onclick=()=>{const blob=new Blob([JSON.stringify({...profile,current:null},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Samolociarze-postepy.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Kopia postępów została pobrana.');};$('importSave').onclick=()=>$('saveFile').click();$('saveFile').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>200000)throw Error('Plik zapisu jest zbyt duży.');profile=sanitizeProfile(JSON.parse(await file.text()));persist();renderProfile();updatePlan();syncSettings();toast('Postępy wczytane.');}catch(error){toast(error.message||'Niepoprawny plik zapisu.');}event.target.value='';};
function syncSettings(){$('soundEnabled').checked=profile.settings.sound;$('ringsEnabled').checked=profile.settings.rings;$('quality').value=profile.settings.quality;configureQuality();}
function cheatMessage(text,error=false){$('cheatMessage').textContent=text;$('cheatMessage').className='fine '+(error?'error':'success');}
$('cheatForm').onsubmit=event=>{event.preventDefault();try{const message=applyCheat(storage,profile,$('cheatCode').value);renderProfile();updatePlan();cheatMessage(message);$('cheatCode').value='';}catch(error){cheatMessage(error.message,true);}};
